static int mxs_auart_request_gpio_irq ( struct mxs_auart_port * s ) { int * irq = s -> gpio_irq ; enum mctrl_gpio_idx i ; int err = 0 ; for ( i = 0 ; ( i < UART_GPIO_MAX ) && ! err ; i ++ ) { irq_set_status_flags ( irq [ i ] , IRQ_NOAUTOEN ) ; err = request_irq ( irq [ i ] , mxs_auart_irq_handle , IRQ_TYPE_EDGE_BOTH , dev_name ( s -> dev ) , s ) ; if ( err ) { dev_err ( s -> dev , "%s - Can't get %d irq\n" , __func__ , irq [ i ] ) ; } } while ( err && ( -- i >= 0 ) ) { if ( irq [ i ] >= 0 ) { free_irq ( irq [ i ] , s ) ; } } return err ; } 